CREATE OR REPLACE FUNCTION public.finalize_license_sale(p_tenant uuid,p_kind text,p_code text,p_quantity integer,p_cadence text,p_price numeric,p_start date,p_payment text,p_request uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v uuid; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(p_request::text,0)); v:=preflight_license_sale(p_tenant,p_kind,p_code,p_quantity,p_cadence,p_price,p_start,p_payment,p_request); IF v IS NOT NULL THEN RETURN v; END IF; RETURN create_license_sale(p_tenant,p_kind,p_code,p_quantity,p_cadence,p_price,p_start,p_payment,p_request); END $$;
REVOKE ALL ON FUNCTION public.finalize_license_sale(uuid,text,text,integer,text,numeric,date,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.finalize_license_sale(uuid,text,text,integer,text,numeric,date,text,uuid) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.create_license_sale(uuid,text,text,integer,text,numeric,date,text,uuid) FROM authenticated;
CREATE OR REPLACE FUNCTION public.validate_partner_sender() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE v text; BEGIN IF length(NEW.settings::text)>16000 THEN RAISE EXCEPTION 'Absenderdaten zu groß'; END IF; IF jsonb_typeof(NEW.settings)<>'object' THEN RAISE EXCEPTION 'Ungültige Absenderdaten'; END IF; FOR v IN SELECT value FROM jsonb_each_text(NEW.settings) LOOP IF length(v)>1000 THEN RAISE EXCEPTION 'Absenderfeld zu lang'; END IF; END LOOP; IF coalesce((NEW.settings->>'payment_terms_days')::int,14) NOT BETWEEN 0 AND 365 OR coalesce((NEW.settings->>'vat_rate')::numeric,19) NOT BETWEEN 0 AND 100 THEN RAISE EXCEPTION 'Ungültiges Zahlungsziel oder Steuer'; END IF; IF coalesce(NEW.settings->>'logo_url','')<>'' AND NEW.settings->>'logo_url' !~ '^https://' THEN RAISE EXCEPTION 'Logo benötigt HTTPS'; END IF; IF coalesce(NEW.settings->>'number_prefix','')<>'' AND NEW.settings->>'number_prefix' !~ '^[A-Za-z0-9-]{1,20}$' THEN RAISE EXCEPTION 'Ungültiger Nummernpräfix'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS validate_partner_sender ON public.partner_billing_settings;
CREATE TRIGGER validate_partner_sender BEFORE INSERT OR UPDATE ON public.partner_billing_settings FOR EACH ROW EXECUTE FUNCTION public.validate_partner_sender();